cat > src/ai/BotPlanner.ts <<'EOF'
import type { ShotCommand } from '../contracts/game';
import type { Vec3 } from '../contracts/math';
import type { Hole, ObstacleDescriptor, SurfaceMaterial } from '../courses/types';
import { createSeededRandom, gaussian, type RandomSource } from './random';
import type { BotPlan, BotPlanningContext, BotProfile, PathAnalysis, ShotCandidate } from './types';

/** Bots never receive the ideal vector: they only probe the hole with a cheap planar rollout. */
export const MAX_SHOT_SPEED = 18;
export const MIN_NORMALIZED_POWER = 0.06;
export const CUP_CAPTURE_SPEED = 4.5;

const STEP = 1 / 60;
const MAX_STEPS = 900;
const STOP_SPEED = 0.15;
const OFF_SURFACE_FRICTION = 7.5;
const FRICTION: Record<SurfaceMaterial, number> = {
  green: 3.4,
  rough: 6.4,
  sand: 11,
  ice: 0.85,
  wood: 3,
  stone: 3.9,
  metal: 2.6,
};

interface Box { minX: number; maxX: number; minZ: number; maxZ: number }

const clamp = (value: number, min: number, max: number): number => Math.min(max, Math.max(min, value));
const distanceXZ = (target: Vec3, x: number, z: number): number => Math.hypot(target.x - x, target.z - z);

const boxOf = (position: Vec3, size: Vec3): Box => ({
  minX: position.x - size.x / 2,
  maxX: position.x + size.x / 2,
  minZ: position.z - size.z / 2,
  maxZ: position.z + size.z / 2,
});

const inside = (box: Box, x: number, z: number): boolean =>
  x >= box.minX && x <= box.maxX && z >= box.minZ && z <= box.maxZ;

const isHazard = (obstacle: ObstacleDescriptor): boolean =>
  obstacle.type === 'water' || obstacle.type === 'void' || obstacle.type === 'reset-zone';

const isMoving = (obstacle: ObstacleDescriptor): boolean =>
  obstacle.type === 'spinner' || obstacle.type === 'windmill' || obstacle.type === 'gate' || obstacle.type === 'platform';

/** Arcade power curve: short putts stay controllable, full power still reaches far. */
export function powerToSpeed(normalizedPower: number): number {
  return MAX_SHOT_SPEED * Math.pow(clamp(normalizedPower, 0, 1), 1.25);
}

export function speedToPower(speed: number): number {
  return clamp(Math.pow(Math.max(speed, 0) / MAX_SHOT_SPEED, 1 / 1.25), 0, 1);
}

function frictionAt(hole: Hole, x: number, z: number): number {
  for (let index = hole.surfaces.length - 1; index >= 0; index -= 1) {
    const surface = hole.surfaces[index];
    if (!inside(boxOf(surface.transform.position, surface.size), x, z)) continue;
    const base = FRICTION[surface.material] ?? FRICTION.green;
    return surface.friction === undefined ? base : base * clamp(surface.friction / 0.6, 0.35, 3);
  }
  return OFF_SURFACE_FRICTION;
}

function obstacleAt(hole: Hole, x: number, z: number): ObstacleDescriptor | undefined {
  for (const obstacle of hole.obstacles) {
    if (obstacle.enabled === false) continue;
    if (inside(boxOf(obstacle.transform.position, obstacle.size), x, z)) return obstacle;
  }
  return undefined;
}

/** Lightweight planar rollout used only for scoring candidates, never for authoritative play. */
export function simulateShot(hole: Hole, from: Vec3, direction: Vec3, normalizedPower: number): { landing: Vec3; analysis: PathAnalysis } {
  const length = Math.hypot(direction.x, direction.z) || 1;
  let dirX = direction.x / length;
  let dirZ = direction.z / length;
  let x = from.x;
  let z = from.z;
  let speed = powerToSpeed(normalizedPower);
  let travel = 0;
  let obstacleHits = 0;
  let hazardPenalty = 0;
  let outOfBounds = false;
  let holed = false;

  for (let step = 0; step < MAX_STEPS && speed > STOP_SPEED; step += 1) {
    speed = Math.max(0, speed - frictionAt(hole, x, z) * STEP);
    if (speed <= STOP_SPEED) break;
    const nextX = x + dirX * speed * STEP;
    const nextZ = z + dirZ * speed * STEP;

    if (distanceXZ(hole.cup.position, nextX, nextZ) <= hole.cup.radius && speed <= CUP_CAPTURE_SPEED) {
      holed = true;
      travel += Math.hypot(nextX - x, nextZ - z);
      x = hole.cup.position.x;
      z = hole.cup.position.z;
      break;
    }

    const blocker = obstacleAt(hole, nextX, nextZ);
    if (blocker) {
      if (isHazard(blocker)) {
        hazardPenalty += blocker.penaltyStrokes ?? 1;
        travel += Math.hypot(nextX - x, nextZ - z);
        x = nextX;
        z = nextZ;
        break;
      }
      const box = boxOf(blocker.transform.position, blocker.size);
      if (x < box.minX || x > box.maxX) dirX = -dirX;
      else dirZ = -dirZ;
      speed *= blocker.type === 'bumper' ? 0.95 : 0.6;
      obstacleHits += isMoving(blocker) ? 2 : 1;
      continue;
    }

    if (nextX < hole.bounds.min.x || nextX > hole.bounds.max.x || nextZ < hole.bounds.min.z || nextZ > hole.bounds.max.z) {
      outOfBounds = true;
      travel += Math.hypot(nextX - x, nextZ - z);
      x = nextX;
      z = nextZ;
      break;
    }

    travel += Math.hypot(nextX - x, nextZ - z);
    x = nextX;
    z = nextZ;
  }

  return {
    landing: { x, y: from.y, z },
    analysis: {
      holed,
      outOfBounds,
      hazardPenalty,
      obstacleHits,
      estimatedTravelDistance: travel,
      estimatedRemainingDistance: holed ? 0 : distanceXZ(hole.cup.position, x, z),
    },
  };
}

function followUpStrokes(remainingDistance: number): number {
  if (remainingDistance <= 0.35) return 0;
  const reach = (MAX_SHOT_SPEED * MAX_SHOT_SPEED) / (2 * FRICTION.green);
  return Math.max(1, Math.ceil(remainingDistance / Math.max(reach * 0.55, 1)));
}

export function scoreCandidate(hole: Hole, from: Vec3, profile: BotProfile, analysis: PathAnalysis): number {
  const { skill, personality } = profile;
  const directDistance = distanceXZ(hole.cup.position, from.x, from.z);
  let score = analysis.holed ? 1000 : 0;
  score -= analysis.estimatedRemainingDistance * 14;
  if (analysis.outOfBounds) score -= 520 * (1.25 - skill.riskTolerance * 0.45);
  score -= analysis.hazardPenalty * 300 * (1.25 - skill.riskTolerance * 0.4);
  score -= analysis.obstacleHits * 22 * (1.15 - skill.shortcutAwareness * 0.75);
  score -= Math.max(0, analysis.estimatedTravelDistance - directDistance * 2.2) * 3;
  if (skill.planningDepth >= 2) {
    score -= followUpStrokes(analysis.estimatedRemainingDistance) * 26 * Math.min(skill.planningDepth, 3);
  }
  if (personality === 'careful') score -= analysis.obstacleHits * 8;
  if (personality === 'trickster') score += Math.min(analysis.obstacleHits, 3) * 6;
  return score;
}

/** Fans candidates around the cup bearing; wider spread for bots that look for bank shots. */
export function generateCandidates(hole: Hole, from: Vec3, profile: BotProfile, random: RandomSource): ShotCandidate[] {
  const samples = clamp(Math.round(profile.skill.simulationSamples), 30, 140);
  const angleSteps = Math.max(5, Math.round(Math.sqrt(samples) * 1.5));
  const powerSteps = Math.max(3, Math.ceil(samples / angleSteps));
  const bearing = Math.atan2(hole.cup.position.z - from.z, hole.cup.position.x - from.x);
  const spread = (Math.PI / 3) * (0.4 + profile.skill.shortcutAwareness * 1.1);
  const directDistance = distanceXZ(hole.cup.position, from.x, from.z);
  const idealPower = clamp(speedToPower(Math.sqrt(2 * FRICTION.green * Math.max(directDistance, 0.5)) * 1.08), MIN_NORMALIZED_POWER, 1);
  const candidates: ShotCandidate[] = [];

  for (let angleIndex = 0; angleIndex < angleSteps; angleIndex += 1) {
    const angleRatio = angleSteps === 1 ? 0.5 : angleIndex / (angleSteps - 1);
    const angle = bearing + (angleRatio * 2 - 1) * spread + (random() - 0.5) * 0.02;
    const direction: Vec3 = { x: Math.cos(angle), y: 0, z: Math.sin(angle) };
    for (let powerIndex = 0; powerIndex < powerSteps; powerIndex += 1) {
      const powerRatio = powerSteps === 1 ? 1 : powerIndex / (powerSteps - 1);
      const normalizedPower = clamp(idealPower * (0.55 + powerRatio * 0.85) + (random() - 0.5) * 0.02, MIN_NORMALIZED_POWER, 1);
      const { landing, analysis } = simulateShot(hole, from, direction, normalizedPower);
      candidates.push({ direction, normalizedPower, landing, analysis, score: scoreCandidate(hole, from, profile, analysis) });
    }
  }
  return candidates;
}

/** Produces a ShotCommand only: the bot never touches input devices or the physics world. */
export function planShot(profile: BotProfile, context: BotPlanningContext): BotPlan {
  const random = createSeededRandom(context.seed ?? `${profile.id}:${context.hole.id}:${context.clientSequence}`);
  const candidates = generateCandidates(context.hole, context.ballPosition, profile, random).sort((a, b) => b.score - a.score);
  const poolSize = clamp(Math.round(2 + profile.skill.riskTolerance * 6), 1, candidates.length);
  const bias = 1 + (1 - profile.skill.riskTolerance) * 2;
  const pickIndex = Math.min(poolSize - 1, Math.floor(Math.pow(random(), bias) * poolSize));
  const chosenCandidate = candidates[pickIndex] ?? candidates[0];
  const angle = Math.atan2(chosenCandidate.direction.z, chosenCandidate.direction.x) + gaussian(random) * profile.skill.aimError * 0.45;
  const normalizedPower = clamp(chosenCandidate.normalizedPower * (1 + gaussian(random) * profile.skill.powerError), MIN_NORMALIZED_POWER, 1);
  const command: ShotCommand = {
    playerId: context.playerId,
    holeId: context.hole.id,
    direction: { x: Math.cos(angle), y: 0, z: Math.sin(angle) },
    normalizedPower,
    clientSequence: context.clientSequence,
    issuedAt: context.issuedAt,
  };
  return { command, chosenCandidate, candidates };
}
